ret.g = GetPixel(mix(uv,uv_orig,0.5)).g* (0.85-0.2*GetBlur1(uv).g) ;
ret.r += texture(sampler_noise_lq,2.0 * uv2)*0.08 * clamp01(1-3*ret.r); //#
  fragColor = vec4(ret, 1.0);
